-- ---------------------------------------------------------------------------
-- FariiFeet — new arrivals, 23 November 2026 (30 shoes)
--
-- The 32 WhatsApp photos that landed in `media/shoes/` on 23 Nov 2026, renamed
-- to kebab-case and copied into `public/shoes/`. Two styles were photographed
-- from two angles, so 32 photos became 30 products:
--   * `vinyl-mule-wine.jpg`   + `vinyl-mule-wine-alt.jpg`
--   * `cc198-runner-grey.jpg` + `cc198-runner-grey-alt.jpg`
--   (the `-alt` shots are kept for a future gallery; only the first is used as
--    `image_url` today)
--
-- Mirrors the "New arrivals — 23 November 2026" block in src/data/products.js,
-- so the offline catalogue and the live table stay identical.
--
-- RUN AFTER `supabase_products_setup.sql` (needs size_range, available_colors
-- and in_stock). Safe to re-run: `on conflict (id) do nothing` leaves rows you
-- have already edited in the dashboard alone.
--
-- PRICES (shop rule): New Balance 45,000 · other sneakers 40,000 ·
--                     heels / pumps / mules / sandals / slides 35,000 TZS.
--
-- IF YOU DELETE A PHOTO: delete its row here and in src/data/products.js, then
--   delete from public.products where id = 'the-id';
-- so the storefront never points at a missing image.
-- ---------------------------------------------------------------------------

insert into public.products (
  id, name, price, image_url, category, size_range, available_colors,
  colorway, badge, blurb, description, details, rating, is_new, is_active,
  in_stock, sort_order
)
values
  ('keyhole-mule-gold', 'Keyhole Peep Mule — Gold', 35000, '/shoes/keyhole-mule-gold.jpg', 'heels', '36 - 45', 'Gold metallic', 'Gold metallic', 'New Drop', 'A liquid-gold mule with a teardrop peep toe.', 'A slim slip-on mule in liquid gold, cut with a teardrop peep toe and set on a low kitten heel. Wear it with denim in the daytime and silk after dark.', array['Metallic patent-look upper', 'Low kitten heel', 'Slip-on peep-toe mule']::text[], 4.8, true, true, true, 220),
  ('keyhole-mule-mint', 'Keyhole Peep Mule — Mint', 35000, '/shoes/keyhole-mule-mint.jpg', 'heels', '36 - 45', 'Mint patent', 'Mint patent', 'New Drop', 'Fresh mint patent on an easy kitten heel.', 'The same sharp peep-toe mule in a cool mint patent that lifts a plain white shirt and jeans. Light on the foot and easy to walk in all day.', array['Mint patent-look upper', 'Low kitten heel', 'Padded footbed']::text[], 4.8, true, true, true, 230),
  ('keyhole-mule-wine', 'Keyhole Peep Mule — Wine', 35000, '/shoes/keyhole-mule-wine.jpg', 'heels', '36 - 45', 'Wine patent', 'Wine patent', 'New Drop', 'Deep wine patent, sharp toe, low heel.', 'A rich wine patent mule with a keyhole peep toe — the pair that makes a simple outfit look deliberate. Covered heel keeps it comfortable from desk to dinner.', array['Wine patent-look upper', 'Low kitten heel', 'Slip-on silhouette']::text[], 4.8, true, true, true, 240),
  ('keyhole-mule-black', 'Keyhole Peep Mule — Black', 35000, '/shoes/keyhole-mule-black.jpg', 'heels', '36 - 45', 'Black patent', 'Black patent', 'New Drop', 'The little black mule that goes with everything.', 'Glossy black patent, a teardrop peep toe and a heel low enough to walk in all evening. The safest pair in the shop — and somehow the most useful.', array['Black patent-look upper', 'Low kitten heel', 'Pointed peep toe']::text[], 4.9, true, true, true, 250),
  ('nb-9060-pink', 'New Balance 9060 — Blush Pink', 45000, '/shoes/nb-9060-pink.jpg', 'sneakers', '36 - 45', 'Blush, Mint', 'Blush / Mint', 'New Drop', 'The sculpted 9060 in a blush-and-mint mash-up.', 'Waved suede overlays, breathable mesh and the sculpted pod midsole that made the 9060 famous — this time in blush pink with mint accents.', array['Mesh & suede upper', '9060 sculpted pod midsole', 'True to size']::text[], 4.8, true, true, true, 260),
  ('nb-9060-white-silver', 'New Balance 9060 — White Silver', 45000, '/shoes/nb-9060-white-silver.jpg', 'sneakers', '36 - 45', 'White, Silver', 'White / Silver', 'New Drop', 'Icy white mesh, silver overlays, chunky sole.', 'An all-white 9060 with silver and grey panelling, finished with the oversized N logo. Clean enough for a dress, chunky enough for a jeans day.', array['Mesh & suede upper', '9060 sculpted pod midsole', 'True to size']::text[], 4.8, true, true, true, 270),
  ('nb-9060-coral-mint', 'New Balance 9060 — Coral Mint', 45000, '/shoes/nb-9060-coral-mint.jpg', 'sneakers', '36 - 45', 'Taupe, Coral, Mint', 'Taupe / Coral / Mint', 'New Drop', 'Taupe and coral on the chunky 9060 sole.', 'Warm taupe mesh with coral and mint overlays — the loudest quiet pair in the shop. The sculpted midsole and wavy panelling do all the talking.', array['Mesh & suede upper', '9060 sculpted pod midsole', 'True to size']::text[], 4.8, true, true, true, 280),
  ('nb-9060-grey', 'New Balance 9060 — Grey Silver', 45000, '/shoes/nb-9060-grey.jpg', 'sneakers', '36 - 45', 'Grey, Silver', 'Grey / Silver', 'New Drop', 'Everyday grey 9060 with silver pops.', 'The neutral 9060 you can wear five days a week: grey mesh, silver overlays, black accents and that oversized sculpted sole. Jeans, leggings, anything.', array['Mesh & suede upper', '9060 sculpted pod midsole', 'True to size']::text[], 4.8, true, true, true, 290),
  ('nb-530-white-cobalt', 'New Balance 530 — White Cobalt', 45000, '/shoes/nb-530-white-cobalt.jpg', 'sneakers', '36 - 45', 'White, Cobalt', 'White / Cobalt', 'New Drop', 'White mesh, cobalt pops, the 530 sole.', 'A fresh white 530 with cobalt-blue accents and silver panelling. Breathable mesh and ABZORB cushioning make it the pair that works from the gym run to the office.', array['Mesh & synthetic upper', 'ABZORB cushioning', 'True to size']::text[], 4.8, true, true, true, 300),
  ('nb-530-white-black', 'New Balance 530 — White Black', 45000, '/shoes/nb-530-white-black.jpg', 'sneakers', '36 - 45', 'White, Black', 'White / Black', 'New Drop', 'The crisp white 530 with black detailing.', 'White mesh and silver overlays with black trim for a cleaner finish. A retro runner that stays quietly in the background of whatever you are wearing.', array['Mesh & synthetic upper', 'ABZORB cushioning', 'True to size']::text[], 4.8, true, true, true, 310),
  ('nb-530-white-navy', 'New Balance 530 — White Navy', 45000, '/shoes/nb-530-white-navy.jpg', 'sneakers', '36 - 45', 'White, Navy', 'White / Navy', 'New Drop', 'White and navy — the pair that never dates.', 'A white 530 with navy accents and a metallic silver frame. Neutral enough for church, sporty enough for the weekend — it never really goes out of style.', array['Mesh & synthetic upper', 'ABZORB cushioning', 'True to size']::text[], 4.8, true, true, true, 320),
  ('nb-530-black', 'New Balance 530 — Triple Black', 45000, '/shoes/nb-530-triple-black.jpg', 'sneakers', '36 - 45', 'Black, White sole', 'Black / White sole', 'New Drop', 'All-black mesh 530 on a bright white sole.', 'The 530 silhouette in a blackout build: black mesh and synthetic overlays, silver N logo, white midsole for contrast. The easiest sneaker to dress up.', array['Mesh & synthetic upper', 'ABZORB cushioning', 'True to size']::text[], 4.9, true, true, true, 330),
  ('gold-ring-thong-black', 'Gold Ring Thong Sandal — Black', 35000, '/shoes/gold-ring-thong-black.jpg', 'slides', '36 - 45', 'Black', 'Black', 'New Drop', 'A flat thong with a polished gold ring.', 'The holiday sandal: a slim flat thong with gold-ring hardware and a softly padded footbed. Light, packable and easy to wear with anything.', array['Flat thong silhouette', 'Gold-tone ring detail', 'Cushioned footbed']::text[], 4.7, true, true, true, 340),
  ('gold-ring-thong-red', 'Gold Ring Thong Sandal — Red', 35000, '/shoes/gold-ring-thong-red.jpg', 'slides', '36 - 45', 'Red', 'Red', 'New Drop', 'A red thong sandal that pops against everything.', 'Bright red straps over a gold ring, on a flat, flexible sole. The pair that turns a plain beach dress into an outfit.', array['Flat thong silhouette', 'Gold-tone ring detail', 'Cushioned footbed']::text[], 4.7, true, true, true, 350),
  ('gold-ring-thong-cognac', 'Gold Ring Thong Sandal — Cognac', 35000, '/shoes/gold-ring-thong-cognac.jpg', 'slides', '36 - 45', 'Cognac tan', 'Cognac tan', 'New Drop', 'Cognac tan with gold — quietly expensive.', 'A tan thong sandal with a gold ring and a neat flat sole. Warm enough to wear from Kariakoo to the beach and back again.', array['Flat thong silhouette', 'Gold-tone ring detail', 'Cushioned footbed']::text[], 4.7, true, true, true, 360),
  ('gold-ring-thong-white', 'Gold Ring Thong Sandal — White', 35000, '/shoes/gold-ring-thong-white.jpg', 'slides', '36 - 45', 'White', 'White', 'New Drop', 'Clean white thong with gold hardware.', 'A crisp white sandal with a gold ring and a soft padded footbed. Simple, fresh and made for hot afternoons.', array['Flat thong silhouette', 'Gold-tone ring detail', 'Cushioned footbed']::text[], 4.7, true, true, true, 370),
  ('patent-pump-blush', 'Patent Point Pump — Blush', 35000, '/shoes/patent-pump-blush.jpg', 'heels', '36 - 45', 'Blush pink', 'Blush pink', 'New Drop', 'A glossy blush stiletto with a clean point.', 'A sharp patent point pump on a slim heel. High enough to lift a look, shaped well enough to wear for hours — and the colour range covers every dress code.', array['Patent-look upper', 'Slim covered heel', 'Pointed toe with padded insole']::text[], 4.8, true, true, true, 380),
  ('patent-pump-white', 'Patent Point Pump — White', 35000, '/shoes/patent-pump-white.jpg', 'heels', '36 - 45', 'White', 'White', 'New Drop', 'Head-turning white patent on a slim heel.', 'A white patent point pump that finishes a jumpsuit, a wedding guest dress or a plain pair of jeans. Classic shape, honest price.', array['Patent-look upper', 'Slim covered heel', 'Pointed toe with padded insole']::text[], 4.8, true, true, true, 390),
  ('patent-pump-caramel', 'Patent Point Pump — Caramel', 35000, '/shoes/patent-pump-caramel.jpg', 'heels', '36 - 45', 'Caramel tan', 'Caramel tan', 'New Drop', 'Caramel patent — the warm neutral heel.', 'A caramel patent point pump that reads richer than black and goes with everything from denim to a wedding kitenge. Slim heel, sharp toe.', array['Patent-look upper', 'Slim covered heel', 'Pointed toe with padded insole']::text[], 4.8, true, true, true, 400),
  ('patent-pump-black', 'Patent Point Pump — Black', 35000, '/shoes/patent-pump-black.jpg', 'heels', '36 - 45', 'Black', 'Black', 'New Drop', 'The black patent point pump every wardrobe needs.', 'A glossy black point pump on a slim covered heel. Interviews, church, dinners, graduations — this is the pair that is never wrong.', array['Patent-look upper', 'Slim covered heel', 'Pointed toe with padded insole']::text[], 4.9, true, true, true, 410),
  ('patent-pump-wine', 'Patent Point Pump — Wine', 35000, '/shoes/patent-pump-wine.jpg', 'heels', '36 - 45', 'Wine', 'Wine', 'New Drop', 'Deep wine patent on a slim, sharp heel.', 'A wine patent point pump with a high-shine finish. Dark enough for evening, warm enough for daytime — a smarter alternative to black.', array['Patent-look upper', 'Slim covered heel', 'Pointed toe with padded insole']::text[], 4.8, true, true, true, 420),
  ('perforated-pump-white', 'Perforated Collar Pump — White', 35000, '/shoes/perforated-pump-white.jpg', 'heels', '36 - 45', 'White', 'White', 'New Drop', 'A point pump with a perforated collar detail.', 'A point-toe pump with a cut-out perforated collar that lets a little skin — and a lot of air — through. Classic heel height, quietly detailed.', array['Perforated collar detail', 'Pointed toe', 'Covered heel with padded insole']::text[], 4.7, true, true, true, 430),
  ('perforated-pump-nude', 'Perforated Collar Pump — Nude', 35000, '/shoes/perforated-pump-nude.jpg', 'heels', '36 - 45', 'Nude', 'Nude', 'New Drop', 'The nude pump that lengthens the leg.', 'A nude point pump with a perforated collar. Close to skin tone, so it disappears on the foot and makes legs look longer — the trick every stylist uses.', array['Perforated collar detail', 'Pointed toe', 'Covered heel with padded insole']::text[], 4.7, true, true, true, 440),
  ('perforated-pump-tan', 'Perforated Collar Pump — Tan', 35000, '/shoes/perforated-pump-tan.jpg', 'heels', '36 - 45', 'Tan', 'Tan', 'New Drop', 'Warm tan patent with a perforated collar.', 'A tan point pump with a perforated collar and a slim covered heel. Works just as well with a work dress as it does with wide-leg trousers.', array['Perforated collar detail', 'Pointed toe', 'Covered heel with padded insole']::text[], 4.7, true, true, true, 450),
  ('perforated-pump-black', 'Perforated Collar Pump — Black', 35000, '/shoes/perforated-pump-black.jpg', 'heels', '36 - 45', 'Black', 'Black', 'New Drop', 'A black point pump with an open perforated collar.', 'Black patent, a sharp point and a perforated collar that keeps the classic pump from feeling predictable. The pair you keep by the door.', array['Perforated collar detail', 'Pointed toe', 'Covered heel with padded insole']::text[], 4.8, true, true, true, 460),
  ('vinyl-mule-wine', 'Vinyl Strap Mule — Wine', 35000, '/shoes/vinyl-mule-wine.jpg', 'heels', '36 - 45', 'Wine, Clear', 'Wine / Clear', 'New Drop', 'Square-toe wine mule with a clear vinyl strap.', 'A modern square-toe mule in deep wine patent, held by a clear vinyl arch strap on a slim heel. Dinner first, after-party second.', array['Patent upper with clear vinyl strap', 'Square toe, kitten heel', 'Backless slip-on fit']::text[], 4.8, true, true, true, 470),
  ('cc198-runner-grey', 'CC198 Chunky Runner — Grey Navy', 40000, '/shoes/cc198-runner-grey.jpg', 'sneakers', '36 - 45', 'Grey, Navy', 'Grey / Navy', 'New Drop', 'A chunky everyday runner in grey and navy.', 'A sporty chunky runner with layered mesh, synthetic overlays and navy accents on the side swoosh. Sculpted cushion midsole for market runs and school pick-ups.', array['Mesh & synthetic upper', 'Sculpted chunky midsole', 'True to size']::text[], 4.6, true, true, true, 480),
  ('sololu-runner-grey-sky', 'Sololu Runner — Grey Sky', 40000, '/shoes/sololu-runner-grey-sky.jpg', 'sneakers', '36 - 45', 'Grey, Sky blue', 'Grey / Sky blue', 'New Drop', 'Low-profile runner in grey mesh and sky blue.', 'A light, low-profile runner with a padded collar and lace-strap grip. The everyday sneaker that works with jeans, skirts and everything in between.', array['Mesh upper with padded collar', 'Cushioned low-profile midsole', 'True to size']::text[], 4.7, true, true, true, 490),
  ('sololu-runner-red-white', 'Sololu Runner — Red White', 40000, '/shoes/sololu-runner-red-white.jpg', 'sneakers', '36 - 45', 'Red, White', 'Red / White', 'New Drop', 'Red mesh runner with a clean white sole.', 'A red-and-white runner that adds the only colour a plain outfit needs. Breathable mesh, padded collar and a flexible white sole.', array['Mesh upper with padded collar', 'Cushioned low-profile midsole', 'True to size']::text[], 4.7, true, true, true, 500),
  ('sololu-runner-white-black', 'Sololu Runner — White Black', 40000, '/shoes/sololu-runner-white-black.jpg', 'sneakers', '36 - 45', 'White, Black', 'White / Black', 'New Drop', 'White mesh, black stripes — the everyday pair.', 'A white runner with black side stripes and a slim cushion sole. Neutral, light and easy to slip on for the school run or a Sunday walk.', array['Mesh upper with padded collar', 'Cushioned low-profile midsole', 'True to size']::text[], 4.7, true, true, true, 510)
